import hashlib
import os
import uuid
import zipfile
from pathlib import Path

import olefile
from fastapi import HTTPException, UploadFile

from .config import settings

ALLOWED = {".docx", ".xlsx", ".doc", ".xls"}


def suffix(name: str) -> str:
    ext = Path(name).suffix.lower()
    if ext not in ALLOWED:
        raise HTTPException(415, "Разрешены только .docx, .doc, .xlsx и .xls.")
    return ext


def blob_path(blob: str) -> Path:
    # Storage keys are generated by the server, never derived from user paths.
    if len(blob) != 32 or any(c not in "0123456789abcdef" for c in blob):
        raise HTTPException(500, "Некорректный ключ хранилища.")
    return settings.data_dir / "blobs" / blob[:2] / blob


def validate_document(path: Path, ext: str) -> None:
    try:
        if ext in {".xlsx", ".docx"}:
            with zipfile.ZipFile(path) as archive:
                items = archive.infolist()
                names = set(archive.namelist())
                required = "xl/workbook.xml" if ext == ".xlsx" else "word/document.xml"
                if (
                    required not in names
                    or "[Content_Types].xml" not in names
                    or len(items) > 10000
                    or sum(i.file_size for i in items) > settings.max_upload_mb * 1024 * 1024 * 20
                    or any(i.flag_bits & 1 for i in items)
                    or any("vbaproject" in n.lower() for n in names)
                    or archive.testzip() is not None
                ):
                    raise ValueError()
        else:
            if not olefile.isOleFile(path):
                raise ValueError()
            with olefile.OleFileIO(path) as doc:
                if ext == ".doc" and not doc.exists("WordDocument"):
                    raise ValueError()
                if ext == ".xls" and not (doc.exists("Workbook") or doc.exists("Book")):
                    raise ValueError()
    except (ValueError, OSError, zipfile.BadZipFile, RuntimeError, EOFError, NotImplementedError):
        raise HTTPException(
            415, "Содержимое не соответствует формату Office или документ повреждён/зашифрован."
        ) from None


async def store_upload(upload: UploadFile, name: str) -> tuple[str, str, int]:
    ext = suffix(name)
    staging = settings.data_dir / "staging"
    staging.mkdir(parents=True, exist_ok=True)
    blob = uuid.uuid4().hex
    temporary = staging / blob
    digest, size = hashlib.sha256(), 0
    try:
        with temporary.open("xb") as target:
            while chunk := await upload.read(1024 * 1024):
                size += len(chunk)
                if size > settings.max_upload_mb * 1024 * 1024:
                    raise HTTPException(413, f"Размер файла превышает {settings.max_upload_mb} МБ.")
                digest.update(chunk)
                target.write(chunk)
            target.flush()
            os.fsync(target.fileno())
        if not size:
            raise HTTPException(415, "Пустой файл.")
        validate_document(temporary, ext)
        destination = blob_path(blob)
        destination.parent.mkdir(parents=True, exist_ok=True)
        os.replace(temporary, destination)
        directory = os.open(destination.parent, os.O_RDONLY)
        try:
            os.fsync(directory)
        finally:
            os.close(directory)
        return blob, digest.hexdigest(), size
    finally:
        temporary.unlink(missing_ok=True)
        await upload.close()
